  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Living in Light of Christ's Return$j$, $j${"prompt": "Revelation teaches that Jesus is alive, that He reigns, and that He will return in victory. How should this change the way a student lives each day? Name one habit or choice you will make because you believe that Jesus is coming again. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Living in Light of Christ's Return$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Revelation: John on Patmos and the Seven Churches$j$, $j${"questions": [{"q": "According to Revelation 1:1, what is the book of Revelation?", "options": ["A list of kings", "The Revelation of Jesus Christ", "A history of Rome", "A book of laws"]}, {"q": "Where was John when he received the vision?", "options": ["In Rome", "In Jerusalem", "In the isle called Patmos", "In Galilee"]}, {"q": "What did Jesus say to the church at Ephesus in Revelation 2:4?", "options": ["You are a faithful church", "You have left your first love", "You have no works", "You are rich"]}, {"q": "What does Jesus say in Revelation 3:20?", "options": ["Build a wall", "I will leave you", "Wait for the end", "I stand at the door, and knock"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Revelation: John on Patmos and the Seven Churches$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,3}'::int[], array[$j$Revelation 1:1 calls the book The Revelation of Jesus Christ.$j$,$j$John was on the isle called Patmos for the word of God and the testimony of Jesus Christ.$j$,$j$Jesus said, Thou hast left thy first love.$j$,$j$Jesus stands at the door and knocks, and He comes in to anyone who opens.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Revelation: John on Patmos and the Seven Churches$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: The Throne in Heaven and the Lamb Who Was Slain$j$, $j${"questions": [{"q": "What did the four living creatures say day and night in Revelation 4:8?", "options": ["Holy, holy, holy, LORD God Almighty", "The end is near", "Glory to the king of Rome", "Peace on earth"]}, {"q": "Why do the elders say God is worthy in Revelation 4:11?", "options": ["Because He rules Rome", "Because He keeps the law", "Because He has created all things", "Because He is the strongest of kings"]}, {"q": "What did John see standing in the midst of the throne in Revelation 5:6?", "options": ["A great eagle", "A mighty king", "A Lamb as it had been slain", "An angel with a sword"]}, {"q": "What did the great multitude from every nation cry in Revelation 7:10?", "options": ["Revenge on the earth", "Judgment to the wicked", "Peace to the world", "Salvation to our God which sitteth upon the throne, and unto the Lamb"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: The Throne in Heaven and the Lamb Who Was Slain$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,3}'::int[], array[$j$They cried, Holy, holy, holy, LORD God Almighty, which was, and is, and is to come.$j$,$j$God is worthy because He created all things.$j$,$j$John saw a Lamb as it had been slain, which is Jesus.$j$,$j$They cried, Salvation to our God which sitteth upon the throne, and unto the Lamb.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: The Throne in Heaven and the Lamb Who Was Slain$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: The Victory of Christ: Faithful and True$j$, $j${"questions": [{"q": "According to Revelation 12:11, how did believers overcome?", "options": ["By the blood of the Lamb and by the word of their testimony", "By building walls", "By escaping to the desert", "By the strength of armies"]}, {"q": "What is the rider on the white horse called in Revelation 19:11?", "options": ["Son of David", "Faithful and True", "Prince of Rome", "Judge of Israel"]}, {"q": "What name is written on the vesture of Christ in Revelation 19:16?", "options": ["KING OF KINGS, AND LORD OF LORDS", "Teacher of the law", "Lamb of the temple", "Prophet of Galilee"]}, {"q": "According to Revelation 20:15, whose names are found in the book of life?", "options": ["Only kings", "Only the old", "Those who trust in Jesus have their names written there", "Only the rich"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: The Victory of Christ: Faithful and True$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,2}'::int[], array[$j$They overcame by the blood of the Lamb, by the word of their testimony, and by loving not their lives unto death.$j$,$j$The rider is called Faithful and True.$j$,$j$His name is KING OF KINGS, AND LORD OF LORDS.$j$,$j$Those whose names are written in the book of life are saved through Jesus.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: The Victory of Christ: Faithful and True$j$ on conflict (item_id) do nothing;
